  '.deck-stage{flex:1;min-height:0;overflow:auto;display:flex;padding:5vh 6vw 2vh;}',
  '.deck-slide{margin:auto;width:100%;max-width:1150px;font-size:clamp(17px,2.1vw,30px);line-height:1.8;animation:deckin .22s ease-out;}',
  '.deck-slide>:first-child{margin-top:0;}',
  '.deck-slide h1{font-size:2.1em;}',
  '.deck-slide h2{font-size:1.6em;}',
  '.deck-slide.title-slide{text-align:center;}',
  '.deck-slide.title-slide h1{background-position:center bottom;background-size:40% 3px;}',
  '@keyframes deckin{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}',
  '.deck-bar{position:absolute;bottom:14px;inset-inline-start:14px;display:flex;align-items:center;gap:4px;padding:4px;border:1px solid var(--border);border-radius:12px;background:var(--surface);opacity:.35;transition:opacity .2s;}',
  '.deck-bar:hover,.deck:not(.idle) .deck-bar{opacity:1;}',
