  '.deck-prog{height:3px;flex:none;background:var(--border);}',
  '.deck-prog i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent-2));transition:width .25s;}',
  '.mdbar{display:flex;align-items:center;gap:2px;flex:none;padding:4px 8px;border-bottom:1px solid var(--border);overflow-x:auto;scrollbar-width:none;}',
  '.mdbar[hidden]{display:none;}',
  '.mdbar::-webkit-scrollbar{display:none;}',
  '.mdb{width:30px;height:28px;flex:none;display:inline-grid;place-items:center;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--ink-2);cursor:pointer;font:inherit;font-size:.86rem;line-height:1;}',
  '.mdb:hover,.mdb[aria-expanded="true"]{background:var(--hover,rgba(127,127,127,.12));color:var(--ink);}',
  '.mdb .i{width:15px;height:15px;}',
