/* --- bidi isolation of LTR runs inside RTL text --- */
function isCodeToken(tok){
  return /[A-Za-z0-9]/.test(tok) && /^[\x21-\x7E]+$/.test(tok)
    && tok.indexOf('<') === -1 && tok.indexOf('>') === -1 && tok.indexOf('"') === -1 && tok.indexOf('&') === -1;
}
var PUNCT_LEAD = /^[(\[{"'“‘«]+/;
var PUNCT_TAIL = /[)\]}"'”’.,;:!?»«،؛؟]+$/;
var BRACKET_OPEN = { ')': '(', ']': '[', '}': '{' };
