/* --- shell line detection (for pasted text whose code fences were lost) --- */
var CMD_RE = /^(?:sudo\s+)?(?:curl|wget|openssl|git|docker|docker-compose|podman|kubectl|helm|ssh|scp|rsync|cd|ls|cat|echo|npm|npx|pnpm|yarn|bun|pip|pip3|uv|python|python3|node|deno|php|composer|go|cargo|make|tar|grep|sed|awk|find|xargs|systemctl|journalctl|service|chmod|chown|mkdir|rm|cp|mv|ln|htop|ps|top|kill|df|du|free|ifconfig|ip|ping|traceroute|dig|nslookup|nc|nmap|ab|wrk|h2load|jq|tee|touch|source|export|env|apt|apt-get|yum|dnf|brew|terraform|ansible|psql|mysql|redis-cli|zap)(?:\s|$)/;
