    if (/^\[.*\]$/.test(v)) v = v.slice(1, -1).split(',').map(function(s){ return s.trim().replace(/^["']|["']$/g, ''); }).filter(Boolean).join('، ');
    if (/^(tags?|tag)$/i.test(k)) tags.push(v);
