    var css = '@page{size:' + dims[0] + 'mm ' + dims[1] + 'mm;margin:' + m[0] + 'mm ' + m[1] + 'mm;'
      + (p.header && title ? '@top-center{content:' + cssString(title) + ';' + box + '}' : '')
