    Array.prototype.forEach.call(clone.querySelectorAll('[data-ui]'), function(n){ n.remove(); });
    Array.prototype.forEach.call(clone.querySelectorAll('.log'), function(n){ n.setAttribute('data-show', el.closest('.log') ? el.closest('.log').getAttribute('data-show') : n.getAttribute('data-show')); });
