    var keyHtml = e.key === null ? '' : '<span class="jk" data-path="' + escapeHtml(e.path) + '" title="کپی مسیر">' + escapeHtml(typeof e.key === 'number' ? String(e.key) : JSON.stringify(e.key)) + '</span><span class="jb">: </span>';
