      + (list.length > 6 ? '<input class="hist-q" id="histQ" type="text" dir="' + (histQuery ? 'auto' : 'rtl') + '" placeholder="جست‌وجو در عنوان و متن…" aria-label="جست‌وجو در متن‌های اخیر" value="' + escapeHtml(histQuery) + '">' : '')
