  '#nb .nb-conflict-row{ border:1px solid var(--border); border-radius:10px; padding:8px; margin:6px 2px; background:var(--surface-2); }',
  '#nb .nb-conflict-row small{ display:block; color:var(--muted); font-size:11px; margin:2px 0 6px; word-break:break-all; }',
  '.nb-cf-btns{ display:flex; gap:8px; flex-wrap:wrap; }',
